def count_is_in_range(
    count: int
) -> bool:
    """Check the ordering comparisons of integers."""
    return (
        (
            0 <= count
            and count < 100
            and (not (count > 99))
            and 99 >= count
        ))


def ratio_is_in_range(
    ratio: float
) -> bool:
    """Check the ordering comparisons of floats."""
    return (
        (
            0.0 <= ratio
            and ratio <= 1.0
            and (not (ratio > 1.0))
            and (0.0) < (1.0 + ratio)
        ))


